function field(k,text,path){const l=labels[k]||[k,k];let content;if(Array.isArray(text))content=`<ul>${text.map((x,i)=>`<li>${dual(x,path+'/'+i)}</li>`).join('')}</ul>`;else if(k==='approvalRef')content=bi('Cách triển khai và ví dụ đang là đề xuất; lựa chọn nói với đội triển khai đã được người dùng xác nhận.','Operational rules and examples are proposed; the user confirmed the team-instruction priority.');else if(k==='authenticity')content=bi('Đặc tính có trong tài liệu thương hiệu; cách triển khai được đề xuất từ nguồn đã đọc.','Traits are documented; implementation is a source-informed proposal.');else content=dual(text,path);return `<div class="v251-field">${bi(...l,'h4')}${content}</div>`}
